class NetworkRequest {
  public:
    std::string url;
    int priority;
    std::function<void(const std::string&)> callback;
};

class PriorityRequestQueue {
  private:
    std::priority_queue<NetworkRequest*, std::vector<NetworkRequest*>, 
                       [](const NetworkRequest* a, const NetworkRequest* b) {
                          return a->priority > b->priority;
                       }> queue_;
  public:
    void enqueue(NetworkRequest* request) {
      queue_.push(request);
    }

    NetworkRequest* dequeue() {
      if (queue_.empty()) return nullptr;
      NetworkRequest* request = queue_.top();
      queue_.pop();
      return request;
    }
};

class NetworkService {
