class RandomNumberGenerator {
 private:
  static RandomNumberGenerator* instance;
  std::mt19937 generator;
  std::map<int, std::uniform_real_distribution<double>> floatDistributions;
  std::map<int, std::uniform_int_distribution<int>> intDistributions;
  std::mutex mutex;

 public:
  static RandomNumberGenerator* getInstance() {
    if (!instance) {
      instance = new RandomNumberGenerator();
    }
    return instance;
  }

  ~RandomNumberGenerator() {}

  void initialize(const uint32_t& seed) {
    std::lock_guard<std::mutex> lock(mutex);
    generator.seed(seed);
  }

  double generateFloat(int stream) const {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = floatDistributions.find(stream);
    if (it == floatDistributions.end()) {
      // Handle missing distribution case (e.g., throw exception or return default value)
    }
    return it->second(generator);
  }

  int generateInt(int stream) const {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = intDistributions.find(stream);
    if (it == intDistributions.end()) {
      // Handle missing distribution case
    }
    return it->second(generator);
  }

  void setDistribution(int stream, double min, double max) {
    std::lock_guard<std::mutex> lock(mutex);
    floatDistributions[stream] = std::uniform_real_distribution<>(min, max);
  }

  void setDistribution(int stream, int min, int max) {
    std::lock_guard<std::mutex> lock(mutex);
    intDistributions[stream] = std::uniform_int_distribution<>(min, max);
  }
};

RandomNumberGenerator* RandomNumberGenerator::instance = nullptr; 
