// Footer.js
class Footer {
  constructor() {
    this._components = [];
    this._footerElement = document.createElement('footer');
  }

  addComponent(component) {
    this._components.push(component);
    this._render();
  }

  _render() {
    this._footerElement.innerHTML = ''; // Clear existing content
    this._components.forEach((component) => component.render(this._footerElement));
  }
}

// ScriptComponent.js
class ScriptComponent {
  constructor({ key, type, code }) {
    if (!key) throw new Error('Script requires a key.');
    if (!type || !/^(?:text|application)\/(?:javascript|x-javascript)$/.test(type)) {
      throw new Error('Invalid script type.');
    }
    this.key = key;
    this.type = type;
    this.code = code.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); 
  }

  render(parent) {
    const script = document.createElement('script');
    script.type = this.type;
    script.key = this.key;
    script.innerHTML = this.code;
    parent.appendChild(script);
  }
}

// HtmlSnippetComponent.js
class HtmlSnippetComponent {
  constructor({ html }) {
    this.html = html;
  }

  render(parent) {
    const div = document.createElement('div');
    div.innerHTML = this.html; // Sanitize HTML here if necessary
    parent.appendChild(div);
  }
}

// WidgetComponent.js
class Widget extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' }); // Shadow DOM for encapsulation
  }

  render(parent) {
    this.shadowRoot.innerHTML = `<div>Widget content</div>`; 
    parent.appendChild(this);
  }
}



// Usage Example
const footer = new Footer();
footer.addComponent(new ScriptComponent({ key: 'my-script', type: 'text/javascript', code: 'console.log("Hello from my script!");' }));
footer.addComponent(new HtmlSnippetComponent({ html: '<h1>Welcome to our website!</h1>' }));
document.body.appendChild(footer._footerElement);

