// ModuleLoader.js
class ModuleLoader {
  constructor(config) {
    this.config = config;
    this.modules = {}; 
    this.dependencyGraph = {}; 
    this.loadedModules = [];
  }

  async loadModule(moduleName) {
    if (this.loadedModules.includes(moduleName)) return;
    const modulePath = this.config.modulePaths[moduleName];
    try {
      const Module = await import(modulePath);
      this.modules[moduleName] = new Module(this); 
      this.loadedModules.push(moduleName); 
      // Handle dependencies...
    } catch (error) {
      console.error(`Error loading module ${moduleName}:`, error);
      throw error; // Re-throw for further handling
    }
  }

