public class DisjointPairProcessor {

    private static final int BATCH_SIZE = 1000;
    private static final String LOG_FILE = "pair_check_log.txt";

    private UnionFind uf; // Optimized Union-Find data structure

    public DisjointPairProcessor() {
        uf = new OptimizedUnionFind(); 
    }

    public void processInteractions(Stream<Interaction> interactions) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
            interactions.parallel()
                    .groupedBy(1000)  // Batch processing for disjoint pair checks
                    .forEach(batch -> {
                        long startTime = Instant.now().toEpochMilli(); 
                        batch.forEach(this::processInteraction); // Process each interaction within a batch
                        long endTime = Instant.now().toEpochMilli();
                        writer.write(String.format("Batch Time: %d ms\n", endTime - startTime));
                    });

        } catch (IOException e) {
            // Handle potential logging errors
        } finally {
            executor.shutdown(); 
        }
    }

    private void processInteraction(Interaction interaction) {
        int userId1 = interaction.getUserId1();
        int userId2 = interaction.getUserId2();
        uf.union(userId1, userId2); // Update Union-Find data structure
    }

    // ... (Methods for network calls, validation, error handling, etc.)

    public static void main(String[] args) {
        DisjointPairProcessor processor = new DisjointPairProcessor();
        processor.processInteractions(loadInteractions()); // Load interactions from file or database
