import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.concurrent.*;

public class AsyncNetworkService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust thread pool size as needed
    private final Selector selector = Selector.open();
    private final ConcurrentHashMap<String, ServerSocketChannel> serverChannels = new ConcurrentHashMap<>(); 
    private final MessageBroker messageBroker;

    public AsyncNetworkService(MessageBroker messageBroker) {
        this.messageBroker = messageBroker;
    }

    public void start(int port) throws IOException {
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.bind(new InetSocketAddress(port));
        serverChannel.configureBlocking(false);
        serverChannels.put("MainServer", serverChannel); 
        // Register the channel for accepting new connections

        selector.register(serverChannel, SelectionKey.OP_ACCEPT);

        while (true) {
            try {
                int readyChannels = selector.select();
                if (readyChannels == 0) {
                    continue; // Handle idle periods efficiently
                }
                for (SelectionKey key : selector.selectedKeys()) {
                    if (!key.isValid()) {
                        continue;
                    }
                    selector.selectedKeys().remove(key);

                    // Process accepted connections, data received, etc.
                    if (key.isAcceptable()) {
                        acceptConnection(key);
                    } else if (key.isReadable()) {
                        handleReadData(key);
                    } // Add other operations like write

                }
            } catch (IOException e) {
                // Handle errors gracefully, log details, and potentially retry
                System.err.println("Error handling channel: " + e.getMessage());
            }
        }
    }

    private void acceptConnection(SelectionKey key) throws IOException {
        ServerSocketChannel serverChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverChannel.accept(); 
        clientChannel.configureBlocking(false);

        // Create a new connection handler thread and register the client channel

        executor.execute(() -> handleClientConnection(clientChannel)); 
    }

