# Initialize Flask app
app = Flask(__name__)

# Configure environment variables
API_URL = os.getenv("API_URL", "https://api.example.com/data")
FALLBACK_DATA = os.getenv("FALLBACK_DATA", "{'message': 'Fallback data'}")
HEALTH_CHECK_TIMEOUT = int(os.getenv("HEALTH_CHECK_TIMEOUT", 5))

# Define API health check function
def check_api_health():
    try:
        response = requests.get(API_URL, timeout=HEALTH_CHECK_TIMEOUT)
        return response.status_code == 200
    except Exception:
        return False

# Initialize API availability flag and fallback data
is_api_available = check_api_health()
current_data = None

# Start health check thread
def monitor_api():
    while True:
        if not is_api_available:
            if check_api_health():
                print("API is back online!")
                is_api_available = True
                current_data = get_data_from_api()
        time.sleep(HEALTH_CHECK_TIMEOUT)

threading.Thread(target=monitor_api).start()

# Define API endpoint
@app.route('/data', methods=['GET'])
def get_data():
    if is_api_available:
        return jsonify(current_data)
    else:
        return jsonify(eval(FALLBACK_DATA)), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=True)
