use futures::{future::retry_on, StreamExt};
use tokio::time;

async fn compile_crate(crate_name: &str) -> Result<CompilationMetrics, Error> {
    let config = load_and_validate_config().await?;
    let build_service_url = config.build_service_url.clone();
    let retry_policy = RetryPolicy::new(3, time::Duration::from_secs(5));

    retry_on(retry_policy).for_future({
        async move {
            let response = reqwest::get(&build_service_url)
                .await
                .map(|res| res.json::<BuildResponse>().await);
            match response {
                Ok(Ok(data)) => Ok(CompilationMetrics {
                    exit_code: data.exit_code,
                    elapsed_time: data.elapsed_time,
                    memory_usage: data.memory_usage,
                }),
                Ok(Err(_)) => Err(Error::InvalidBuildResponse),
                _ => Err(Error::RemoteServiceUnavailable),
            }
        }
    })
    .await
}

#[derive(Debug)]
struct CompilationMetrics {
    exit_code: i32,
    elapsed_time: Duration,
    memory_usage: usize,
}

#[derive(Debug)]
enum Error {
    InvalidBuildResponse,
    RemoteServiceUnavailable,
    ConfigValidationFailed,
}


