# json_utils/json_serializer.py
class JSONSerializer:
    def __init__(self, config_service):
        self.config_service = config_service

    def serialize(self, obj):
        schema = self.config_service.get_schema(obj.__class__.__name__)
        return json.dumps(obj, default=lambda o: o.__dict__, indent=4, sort_keys=True)

    def deserialize(self, data, cls):
        schema = self.config_service.get_schema(cls.__name__)
        try:
            return schema.loads(data)
        except ValidationError as e:
            raise DeserializationError(f"Invalid JSON data: {e}")

# json_utils/factory.py
class FactoryRegistry:
    def __init__(self):
        self._factories = {}

    def register(self, id, factory):
        self._factories[id] = factory

    def create(self, id):
        if id not in self._factories:
            raise KeyError(f"Factory ID {id} not registered")
        return self._factories[id]()


# json_utils/config_service.py
class ConfigService:
    def __init__(self, schema_endpoint):
        self.schema_endpoint = schema_endpoint

    def get_schema(self, object_type):
        response = requests.get(f"{self.schema_endpoint}/{object_type}")
        if response.status_code == 200:
            return json.loads(response.content)
