using System;
using System.Threading;
using System.Security;

public class RandomValueGenerator
{
    private readonly float min;
    private readonly float max;
    private readonly object lockObj = new object(); 

    public RandomValueGenerator(string minStr, string maxStr)
    {
        if (!float.TryParse(minStr, out this.min) || !float.TryParse(maxStr, out this.max))
        {
            throw new ArgumentException("Invalid input format. Please provide valid numeric values for minimum and maximum.");
        }

        if (this.min >= this.max)
        {
            throw new ArgumentException("Minimum value cannot be greater than or equal to the maximum value.");
        }
    }


    public float GenerateRandomFloat(bool inclusive = true)
    {
        lock (lockObj)
        {
            float randomValue; 
            if (inclusive)
            {
                randomValue = UnityEngine.Random.Range(this.min, this.max + 1);
            }
            else
            {
                randomValue = UnityEngine.Random.Range(this.min, this.max);
            }

            return randomValue;
        }
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        lock (lockObj)
        {
            int randomValue; 
            if (inclusive)
            {
                randomValue = UnityEngine.Random.Range((int)this.min, (int)(this.max + 1));
            }
            else
            {
                randomValue = UnityEngine.Random.Range((int)this.min, (int)this.max);
            }

            return randomValue;
        }
    }


    public string GetRangeInfo()
    {
        return $"Minimum: {this.min}, Maximum: {this.max}"; 
    }   
}
