    void *user_data;
} LoadResourceBundleRequest;

typedef struct {
    pthread_mutex_t mutex;
    LoadResourceBundleRequest *requests[1024]; // Assuming max concurrent requests
    int request_count;
} ResourceLoader;

static ResourceLoader loader = {
    PTHREAD_MUTEX_INITIALIZER, 
    NULL, 
    0
};


void *load_resource_bundle_thread(void *arg) {
    LoadResourceBundleRequest *request = (LoadResourceBundleRequest *)arg;
    // ... (Logic for loading the resource bundle asynchronously)
    // ... (Handle errors and logging)
    request->callback(request->user_data, /* success/failure status */);
    free(request);
    return NULL;
}

int load_resource_bundle(const char *path, load_resource_bundle_callback callback, void *user_data) {
    pthread_mutex_lock(&loader.mutex);
    LoadResourceBundleRequest *request = malloc(sizeof(LoadResourceBundleRequest));
    request->path = strdup(path); 
    request->callback = callback;
    request->user_data = user_data;

    loader.requests[loader.request_count++] = request;
    pthread_mutex_unlock(&loader.mutex);

    // ... (Start a new thread to load the bundle asynchronously)
    return 0; 
}



```


**Explanation:**

1. **Data Structures:**
   - `LoadResourceBundleRequest`: Holds information about each resource bundle loading request, including the file path, callback function, and user data.

2. **ResourceLoader:** Manages concurrent loading requests using a mutex and an array of `LoadResourceBundleRequest` structs.
3. **load_resource_bundle_thread:** A worker thread responsible for asynchronously loading a single resource bundle. It handles errors, logs events, and calls the provided callback function upon completion.

4. **load_resource_bundle Function:**  
   - Takes the file path, callback function, and user data as input.
   - Acquires a lock on the `loader` mutex to ensure thread safety when adding a new request. 
   - Creates a `LoadResourceBundleRequest` and adds it to the `loader.requests` array.
   - Releases the mutex. 
   - Starts a new thread using `pthread_create` to execute the `load_resource_bundle_thread` function for the added request.


