    }

    private void deserializeAndProcess(byte[] data) throws IOException, ClassNotFoundException { 
        List<Object> entities = objectMapper.readValue(new ByteArrayInputStream(data), List.class); 
        for (Object entity : entities) {
            processEntity(entity); 
        }
    }

    private void processEntity(Object entity) {
        // Perform further processing on each deserialized entity...
    }

    private void loadMetadata() {
        Map<String, String> metadata = metadataFetcher.fetchMetadata();
        for (Map.Entry<String, String> entry : metadata.entrySet()) {
            String className = entry.getValue(); 
            entityClassMap.putIfAbsent(entry.getKey(), getClassByName(className)); 
        }
    }

    private Class<?> getClassByName(String className) {
        try {
            return Class.forName(className);
        } catch (ClassNotFoundException e) {
            LOGGER.warn("Could not find class: " + className, e);
            // Handle missing classes gracefully 
            return null; 
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.MINUTES)) {
                LOGGER.warn("Executor did not terminate within timeout.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); 
        }
    }

}



```



