    public OAuthTokenValidator(int minExpirationSeconds, int maxExpirationSeconds)
    {
        if (minExpirationSeconds >= maxExpirationSeconds)
        {
            throw new ArgumentException("Minimum expiration time must be less than maximum.");
        }

        _minExpiration = TimeSpan.FromSeconds(minExpirationSeconds);
        _maxExpiration = TimeSpan.FromSeconds(maxExpirationSeconds);
    }

