            // If any validation fails, return false.

            string accessToken = GetAccessTokenFromJson(tokenJson);
            DateTime expirationTime = CalculateExpirationTimeFromToken(tokenJson);

            if (_validatedTokens.ContainsKey(accessToken) &&  expirationTime > DateTime.UtcNow)
            {
                return true;
            }

            // Perform external validation via AS
            bool isValid = ExternalValidateAccessToken(accessToken, expirationTime); 

            if (isValid)
            {
                _validatedTokens[accessToken] = expirationTime;
