class ServiceHealthWorker {
public:
    ServiceHealthWorker() : timer(std::chrono::seconds(config.healthCheckInterval)) {}

    void run() {
        while (true) {
            for (auto& service : services) {
                if (service->isHealthy()) {
                    continue; // Healthy service, skip check
                }

                // Perform health check and send notification if unhealthy
                if (!checkHealth(service)) {
                    sendNotification(service, "Service Down", 
                                      service->getEndpoint());
                } else {
                    sendNotification(service, "Service Restored", 
                                      service->getEndpoint());
                }

                // Adjust retry intervals based on backoff strategy
            }
            timer.wait();
        }
    }

