using System.Threading.Tasks;

namespace GameWorldConfig
{
    public class ConfigManager
    {
        private readonly HttpClient _httpClient = new();
        private readonly string _apiUrl = "https://api.example.com/config";
        private volatile Dictionary<string, dynamic> _currentConfig = new();
        private object _lock = new object();

        public async Task LoadConfigAsync()
        {
            try
            {
                var response = await _httpClient.GetAsync(_apiUrl);
                response.EnsureSuccessStatusCode();
                _currentConfig = await response.Content.ReadAsAsync<Dictionary<string, dynamic>>();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading config: {ex.Message}");
                // Implement fallback to cached or default values
            }
        }

        public void UpdateConfig(string key, dynamic value)
        {
            lock (_lock)
            {
                _currentConfig[key] = value;
            }
        }

        public T GetConfigValue<T>(string key)
        {
            lock (_lock)
            {
                if (_currentConfig.ContainsKey(key))
                {
                    return (T)_currentConfig[key];
                }
                // Implement fallback to default value
                return default;
            }
        }

        public static void Main(string[] args)
        {
            var configManager = new ConfigManager();

            // Load initial configuration
            configManager.LoadConfigAsync().Wait();

            // Console interface for manual updates and display current settings
            while (true)
            {
                Console.WriteLine("Current Configuration:");
                foreach (var kvp in configManager._currentConfig)
                {
                    Console.WriteLine($"{kvp.Key}: {kvp.Value}");
                }

                Console.Write("Enter key to update (or 'exit' to quit): ");
                string key = Console.ReadLine();
                if (key.ToLower() == "exit")
                {
                    break;
                }
                Console.Write("Enter new value: ");
                dynamic newValue = Convert.ChangeType(Console.ReadLine(), typeof(object));
                configManager.UpdateConfig(key, newValue);
            }
        }
    }
}
