import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Configuration;

// ... Other imports and dependencies

@Configuration
public class SecureStringProcessor {

    @Autowired
    private SaltProvider saltProvider;

    @Autowired
    private HashingAlgorithmFactory hashingAlgorithmFactory;

    @Autowired
    private CacheManager cacheManager;

    @Autowired
    private LogService logService;

    public String generateSecureHash(String input) throws BadRequestException {
        if (input == null || input.isEmpty()) {
            throw new BadRequestException("Input string cannot be null or empty.");
        }

        String salt = saltProvider.getSalt(); 
        HashingAlgorithm algorithm = hashingAlgorithmFactory.getAlgorithm();
        String hash = algorithm.generateHash(input, salt);

        cacheManager.put(input, hash);
        logService.logHashGeneration(input, salt, hash);
        return hash;
    }

    // ... Other methods for retrieval, invalidation, etc. 
}



```


