  const connection = await queue.connect('amqp://localhost');
  const channel = await connection.createChannel();
  channel.assertQueue('log-queue'); // Assert queue existence

  channel.consume('log-queue', (message) => {
    processLogs(JSON.parse(message.content.toString()));
  });
};

// Start the microservice
