void loadResourceBundleAsync(const char* path, void (*callback)(CachedResourceBundle*)) {
    pthread_t thread;
    CachedResourceBundle* cache = malloc(sizeof(CachedResourceBundle));
    cache->loaded = false; 

    int rc = pthread_create(&thread, NULL, 
                           [](void* arg) { // Thread function
        CachedResourceBundle* cache = (CachedResourceBundle*)arg;
        // ... Implement asynchronous resource loading logic ...
        pthread_mutex_lock(&cache->mutex);
        cache->loaded = true;
        cache->bundle.path = path; 
        // ... Set bundle content and size after loading ... 
        pthread_mutex_unlock(&cache->mutex);

        callback(cache); // Notify callback on completion
    }, cache);
    if (rc) {
        fprintf(stderr, "Error creating thread: %d\n", rc);
    }
}


```



