    private readonly IDataFetcher _dataFetcher;
    private readonly IDecryptor _decryptor;
    private readonly ISerializer _serializer;

    public DataProcessingPipeline(IDataFetcher dataFetcher, IDecryptor decryptor, ISerializer serializer)
    {
        _dataFetcher = dataFetcher;
        _decryptor = decryptor;
        _serializer = serializer;
    }

    public async Task<T> ProcessDataAsync<T>(string filePath)
    {
        // 1. Fetch encrypted data from storage based on filePath and configured service (Azure Blob Storage or Amazon S3).
        var encryptedData = await _dataFetcher.FetchDataAsync(filePath);

        // 2. Decrypt the fetched data using _decryptor.
        var decryptedData = _decryptor.Decrypt(encryptedData);

        // 3. Deserialize the decrypted data into the desired type T using _serializer.
        return _serializer.Deserialize<T>(decryptedData);
    }
}

// ... (Implement interfaces IDataFetcher, IDecryptor, ISerializer with concrete implementations for Azure Blob Storage, Amazon S3, etc.)
