    private final MetadataService metadataService;
    private final int numWorkerThreads;
    private final ThreadPoolExecutor executor;
    private final Cache<String, Deserializer> deserializerCache;

    public SerializationService(MetadataService metadataService, int numWorkerThreads) {
        this.metadataService = metadataService;
        this.numWorkerThreads = numWorkerThreads;
        this.executor = new ThreadPoolExecutor(
                numWorkerThreads,
                numWorkerThreads,
                60L, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>()
        );
        this.deserializerCache = new ConcurrentHashMap<>();
    }

    public void processStream(InputStream inputStream) {
        byte[] buffer = new byte[1024];
        try {
            while (inputStream.read(buffer) != -1) {
                executor.execute(() -> deserializeAndProcess(buffer)); 
            }
        } catch (IOException e) {
            // Handle IOExceptions gracefully, e.g., log and retry
        } finally {
            try {
                inputStream.close();
            } catch (IOException e) {
                // Handle closing exceptions
            }
        }
    }

    private void deserializeAndProcess(byte[] data) {
        String entityType = metadataService.getSchemaForEntity(data); // Schema lookup
        Deserializer deserializer = deserializerCache.computeIfAbsent(entityType, t -> {
            return new Deserializer(metadataService.getSchemaDefinition(t));
        });
        SerializableEntity entity = deserializer.deserialize(data); 
