  try {
    const response = await axios.get(`https://secrets-manager.com/api/v1/environments/${environment}/tokens`); 
    return response.data;
  } catch (error) {
    console.error('Error fetching token:', error);
    throw new Error('Failed to fetch access token from secrets manager');
  }
}

// Function to decrypt the retrieved token
