  try {
    const privateKey = 'YOUR_PRIVATE_KEY'; // Replace with your private key
    return jwt.verify(encryptedToken, privateKey); 
  } catch (error) {
    console.error('Error decrypting token:', error);
    return null; // Return null on decryption failure
