pthread_mutex_t measurement_lock; 
CellMeasurement* measurements = NULL;
size_t measurement_count = 0;
size_t measurement_capacity = 0;

// Function to add a new measurement record
void add_measurement(CellMeasurement measurement) {
    pthread_mutex_lock(&measurement_lock); 
    if (measurement_count == measurement_capacity) {
        // Resize the array if necessary
        measurement_capacity *= 2;
        measurements = realloc(measurements, measurement_capacity * sizeof(CellMeasurement));
    }
    measurements[measurement_count++] = measurement;
    pthread_mutex_unlock(&measurement_lock);
}

// Function to remove old measurements based on duration
void clean_up_measurements(int duration) {
    time_t now = time(NULL);
    size_t i = 0;
    while (i < measurement_count) {
        if (now - measurements[i].timestamp > duration) {
            // Shift remaining elements to fill the gap
            memmove(&measurements[i], &measurements[i + 1], (measurement_count - i - 1) * sizeof(CellMeasurement));
            measurement_count--;
        } else {
            i++;
        }
    }
}

