<?php
class UserDAO {
    private $dbConnection;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function updatePassword(string $userId, string $newPassword): bool {
        // Validate password strength (e.g., length, complexity)
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $newPassword)) {
            // Handle invalid password
            return false;
        }

        // Securely hash the new password (e.g., bcrypt)
        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        // Update user's password in database using prepared statement
        $stmt = $this->dbConnection->prepare("UPDATE users SET password = ? WHERE id = ?");
        $stmt->bind_param("ss", $hashedPassword, $userId);
        if ($stmt->execute()) {
            return true; 
        } else {
            // Handle database error
            return false;
        }
    }
}

?>
