    public DataProcessingPipelineBuilder AddProcessor<T>(Func<T, Task> processor) where T : class
    {
        _processors.Add(new ProcessorWrapper<T>(processor));
        return this;
    }

    // ... (Methods for configuring EventBus, Error Handling, Retry Policies, etc.)

    public async Task RunAsync()
    {
        foreach (var processor in _processors)
        {
            await processor.ProcessDataAsync(_eventBus); 
        }
    }
}



public class ProcessorWrapper<T> : IDataProcessor
{
    private readonly Func<T, Task> _processor;

    // ... (Constructor and Logic for processing data asynchronously with retries)
}

// ... (Classes for Event Bus, Data Sources, Message Broker Integration, etc.)




