    public async Task<WebsiteInfo> AddWebsiteAsync(string directoryPath, string siteName)
    {
        // Distributed lock acquisition for concurrency control 
        var lockKey = $"website-add-{siteName}";
        await _redisClient.AcquireLockAsync(lockKey); // Acquire distributed lock

        try
        {
            // Validate web.config file (health check)
            if (!ValidateWebConfig(directoryPath))
            {
                return null; 
            }

            // IIS website addition using COM interop
            var siteInfo = await _iisAdministrationService.AddWebsiteAsync(directoryPath, siteName); //  

            return siteInfo; 
        }
        catch (Exception ex)
        {
            // Log error details
            LogException($"Error adding website '{siteName}' - {ex.Message}");
            // Handle exception gracefully, potentially retrying or notifying a monitoring system
            throw; // Re-throw to propagate the error 
        }
        finally
        {
            _redisClient.ReleaseLock(lockKey); // Release lock
        }
    }

