    public async Task<TransactionResult> ProcessTransaction(Transaction transaction)
    {
        var retryCount = 0;
        while (retryCount < MaxRetries)
        {
            foreach (var processor in _processors.OrderByDescending(p => p.HealthScore))
            {
                if (processor.IsAvailable)
                {
                    try
                    {
                        return await processor.ProcessTransactionAsync(transaction); 
                    }
                    catch (Exception ex)
                    {
                        Logger.LogError($"Transaction failed on {processor.Name}: {ex.Message}");
                        await Task.Delay(TimeSpan.FromMilliseconds(Math.Pow(2, retryCount) * 100 + Random.Shared.Next(50))); // Exponential backoff with jitter
                        retryCount++;
                    }
                }
            }
            // Transaction failed after all retries
            return new TransactionResult { Success = false, ErrorMessage = "All processors failed to process transaction" };
        }

    }
}


