public class PokemonWeaknessMicroservice {

    private final TypeApiService typeApiService; // Primary API client
    private final FallbackTypeApiService fallbackApiService; // Secondary API client
    private final WeaknessAnalyzer weaknessAnalyzer; 
    private final CacheManager cacheManager; // Distributed caching implementation

    // Constructor for dependency injection
    public PokemonWeaknessMicroservice(TypeApiService typeApiService, FallbackTypeApiService fallbackApiService, WeaknessAnalyzer weaknessAnalyzer, CacheManager cacheManager) {
        this.typeApiService = typeApiService;
        this.fallbackApiService = fallbackApiService;
        this.weaknessAnalyzer = weaknessAnalyzer;
        this.cacheManager = cacheManager;
    }

    // Endpoint to fetch Pokémon weaknesses
    @GetMapping("/pokemon/{name}/weaknesses")
    public ResponseEntity<WeaknessesReport> getPokemonWeaknesses(@PathVariable String name) {
        String cachedData = cacheManager.get(name); 

        if (cachedData != null) {
            return new ResponseEntity<>(JSON.parseObject(cachedData), HttpStatus.OK);
        }

        // Type data retrieval and fallback mechanism
        Type type = getPokemonType(name); // Fetch primary source

        // Weakness analysis and report generation
        WeaknessesReport weaknessesReport = weaknessAnalyzer.analyzeWeaknesses(type);

        cacheManager.put(name, JSON.toJSONString(weaknessesReport)); 
        return new ResponseEntity<>(weaknessesReport, HttpStatus.OK);
    }

    // Helper method to retrieve Pokémon type from APIs (primary and fallback)
    private Type getPokemonType(String name) {
        try {
            return typeApiService.getTypeByName(name); // Primary API call
        } catch (ApiException e) {
            log.error("Primary API error: {}", e.getMessage());
            return fallbackApiService.getTypeByName(name); // Fallback API call
        }
    } 

}



