};

class DataProcessingFramework {
private:
    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable cv;

    std::vector<EncryptionWorker*> workers;
    int workerCount = std::thread::hardware_concurrency(); // Dynamically adjust worker count based on available cores

public:
    DataProcessingFramework() {
        for (int i = 0; i < workerCount; ++i) {
            workers.push_back(new EncryptionWorker());
            std::thread workerThread([this]() { 
                while (true) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    cv.wait(lock, [this] { return !dataQueue.empty(); });
                    std::string data = dataQueue.front();
                    dataQueue.pop();
                    lock.unlock();

                    workers[i]->processData(data); 
                }
            });
            workerThread.detach(); 
        }
    }

    ~DataProcessingFramework() {
        // ... Graceful shutdown and cleanup of workers
    }

    void enqueueData(const std::string& data) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            dataQueue.push(data); 
        }
        cv.notify_one(); // Wake up a waiting worker thread
    }
};

int main() {
    DataProcessingFramework framework; 
