use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    match args.as_slice() {
        [..1] => println!("Please provide a command."),
        [cmd, ..] => match cmd.as_str() {
            "add" => add(&args),
            "subtract" => subtract(&args),
            "multiply" => multiply(&args),
            _ => println!("Invalid command."),
        },
    }
}

fn add(args: &[String]) {
    let num1 = args[1].parse::<f64>().unwrap();
    let num2 = args[2].parse::<f64>().unwrap();
    println!("{} + {} = {}", num1, num2, num1 + num2);
}

fn subtract(args: &[String]) {
    let num1 = args[1].parse::<f64>().unwrap();
    let num2 = args[2].parse::<f64>().unwrap();
    println!("{} - {} = {}", num1, num2, num1 - num2);
}

fn multiply(args: &[String]) {
