void init_crclist(CRCList *list) {
  list->entries = NULL;
  list->size = 0;
  list->capacity = 0;
  pthread_mutex_init(&list_mutex, NULL);
}

void destroy_crclist(CRCList *list) {
  for (int i = 0; i < list->size; i++) {
    free(list->entries[i]);
  }
  free(list->entries);
  pthread_mutex_destroy(&list_mutex);
}

