function deserialize_oauth2_token($json) {
    if (json_decode($json) === null) {
        return false; // Handle JSON parsing errors
    }

    $data = json_decode($json, true);

    if (!isset($data['access_token']) || !isset($data['expires_in']) || !isset($data['token_type'])) {
        return false; // Required fields missing
    }

    if ($data['token_type'] !== 'Bearer') {
        return false; // Invalid token type
    }

    if (!is_numeric($data['expires_in']) || $data['expires_in'] <= 0) {
        return false; // Invalid expires_in value
    }

    // ... (Optional: Handle refresh_token, etc.)

    return true; 
}



