// Dependencies
const kafka = require('kafka-node');
const redis = require('redis');

// Configuration (loaded from environment variables)
const KAFKA_BROKERS = process.env.KAFKA_BROKERS;
const REDIS_HOST = process.env.REDIS_HOST;
const JOB_TOPIC = process.env.JOB_TOPIC;
const LOCK_PREFIX = process.env.LOCK_PREFIX;

// Kafka consumer and producer
const kafkaConsumer = new kafka.Consumer(
  new kafka.KafkaClient({ brokers: KAFKA_BROKERS }),
  [{ topic: JOB_TOPIC, partition: 0 }],
  {
    autoCommit: false, // Manual commit for distributed locking
  }
);

const kafkaProducer = new kafka.KafkaClient({ brokers: KAFKA_BROKERS });

// Redis client for distributed locking
const redisClient = redis.createClient(REDIS_HOST);

// Job processing function (example)
async function processJob(jobData) {
  try {
    // Acquire lock using Redis
    await redisClient.set(LOCK_PREFIX + jobData.id, 'processing', 'EX', 60); // Lock duration: 60 seconds

    // Call external APIs (asynchronously if possible)
    const response = await axios.get(`https://external-api/${jobData.data}`);

    // Process the API response
    // ...

    // Release the lock
    await redisClient.del(LOCK_PREFIX + jobData.id);

  } catch (error) {
    console.error('Job processing failed:', error);
    // Handle errors and potentially retry or reschedule jobs
  } finally {
    // Acknowledge message to Kafka consumer
    kafkaConsumer.commitMessage({
      topic: JOB_TOPIC,
      partition: 0,
      messages: [
        {
          key: jobData.id,
          value: JSON.stringify(jobData),
        },
      ],
    });
  }
}

// Kafka consumer event handler
kafkaConsumer.on('message', async (message) => {
  try {
    const jobData = JSON.parse(message.value);
    await processJob(jobData);
  } catch (error) {
    console.error('Error processing message:', error);
    // Handle errors and potentially retry or reschedule jobs
  }
});

// Start the service
kafkaConsumer.on('ready', () => {
  console.log('Kafka consumer ready');
});
```



