    loop {
        println!("Enter target string:");
        let mut target = String::new();
        std::io::stdin().read_line(&mut target).unwrap();

        println!("Enter insertion string:");
        let mut insertion = String::new();
        std::io::stdin().read_line(&mut insertion).unwrap();

        let request = InsertStringRequest {
            target: target.trim().to_string(),
            insertion: insertion.trim().to_string(),
            insert_at_end: false, // Example: change as needed
        };

        // Send the RPC request asynchronously and handle the response
        let future = rpc_client.call("insertString", request); 

        match future {
            Ok(response) => {
                println!("Response: {:?}", response);
            }
            Err(error) => {
                println!("Error: {}", error);
            }
        }
    }
}



