import java.io.*;

public class FileDeleteAndExec {

    public static void main(String[] args) throws IOException, InterruptedException {
        // Specify the file to delete and the command to execute
        String filePath = "target/my_file.txt"; 
        String command = "ls -l";  

        // Delete the existing file (if any)
        File fileToDelete = new File(filePath);
        if (fileToDelete.exists()) {
            fileToDelete.delete();
            System.out.println("File deleted: " + filePath);
        } else {
            System.out.println("File not found: " + filePath);
        }

        // Execute the command and read its output and error streams
        Process process = Runtime.getRuntime().exec(command, null, new File("/path/to/working/directory")); 
        BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String outputLine;
        while ((outputLine = stdOutput.readLine()) != null) {
            System.out.println("Output: " + outputLine);
        }

        String errorLine;
        while ((errorLine = stdError.readLine()) != null) {
            System.out.println("Error: " + errorLine);
        }

        // Wait for the command to finish execution
        process.waitFor(); 
    }
}
```



