#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// ... Structure definitions for NFAPI Measurement Report, Thread Safe Queue, etc.

pthread_mutex_t report_queue_mutex; 
pthread_cond_t  report_available_cond;

typedef struct {
    int rSRP;
    int cQI;
    struct timespec timestamp;
} MeasurementReport;

typedef struct {
    MeasurementReport* reports;
    int size;
    int head;
    int tail;
} ReportQueue;


void initialize_report_queue(ReportQueue* queue) {
    queue->reports = malloc(sizeof(MeasurementReport) * 1024); // Initial allocation
    queue->size = 1024;
    queue->head = 0;
    queue->tail = 0;

    pthread_mutex_init(&report_queue_mutex, NULL);
    pthread_cond_init(&report_available_cond, NULL);
}

void enqueue_measurement_report(ReportQueue* queue, MeasurementReport report) {
    pthread_mutex_lock(&report_queue_mutex); 
    // ... Handle full queue scenario with overflow management
    queue->reports[queue->tail] = report; 
    queue->tail = (queue->tail + 1) % queue->size; 
    pthread_cond_signal(&report_available_cond);  
    pthread_mutex_unlock(&report_queue_mutex);
}

MeasurementReport dequeue_measurement_report(ReportQueue* queue) {
    pthread_mutex_lock(&report_queue_mutex); 
    while (queue->head == queue->tail) {
        pthread_cond_wait(&report_available_cond, &report_queue_mutex); 
    }
    MeasurementReport report = queue->reports[queue->head]; 
    queue->head = (queue->head + 1) % queue->size; 
    pthread_mutex_unlock(&report_queue_mutex);
    return report;
}

// ... Implement other functions for external service integration, error handling, logging, configuration, etc.


int main() {
   ReportQueue measurement_reports;
   initialize_report_queue(&measurement_reports);

   pthread_t measurement_thread;
   pthread_create(&measurement_thread, NULL, measurement_thread_function, NULL); 
   // ... Start other threads as needed for data processing, reporting, etc.

    return 0;
}
```


**Explanation of the Code:**


* **Data Structures:** The code defines `MeasurementReport` to hold RSRP, CQI and timestamp data and a `ReportQueue` to manage the reports efficiently with thread safety.
* **Threading:**  The code uses pthread for concurrency. A dedicated thread (`measurement_thread`) is created to handle incoming measurements from the external service.
* **Synchronization:** 
    * `pthread_mutex_t`:  Used to protect shared data (the `ReportQueue`) from race conditions during concurrent access.
    * `pthread_cond_t`: Used for signaling between threads:
        * The `measurement_thread` waits on `report_available_cond` if the queue is empty.
        * When a new report is enqueued, `pthread_cond_signal()` wakes up waiting threads in `dequeue_measurement_report`.

* **Error Handling:**
    * Placeholder comments (`// ... Handle full queue scenario with overflow management`) indicate where you'd implement strategies like circular buffers or dynamic resizing of the `ReportQueue` to handle overfilling. 
