        if (!float.TryParse(min, out parsedMin) || !float.TryParse(max, out parsedMax))
        {
            throw new ArgumentException("Invalid input format. Both arguments must be numeric.");
        }

        if (parsedMin >= parsedMax)
        {
            throw new ArgumentException("Minimum value must be less than the maximum value.");
        }

        _min = parsedMin;
        _max = parsedMax;
    }

    public float GenerateRandomFloat(bool inclusive = true)
    {
        lock (_lock)
        {
            // ... (Implement caching logic for random float generation) 
            return (float)(inclusive ? _min : _min + .0001f) + new Random().NextDouble() * ((inclusive ? (_max - _min) : (_max - _min - .0001f)));
        }
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        lock (_lock)
        {
            // ... (Implement caching logic for random integer generation) 
            return (int)(inclusive ? _min : _min + .5f) + new Random().Next((int)((!inclusive ? _max - _min - .0001f : _max - _min))), (int)((!inclusive ? _max - _min - .0001f : _max - _min)));
        }
    }

    public string GetRangeInfo()
    {
        lock (_lock)
        {
            return $"Range: {_min} to {_max}";
        }
    }
}

