import threading
import time

class Tracer:
    def __init__(self):
        self.spans = [] 
        self.tags = {}
        self.events = []

    def start_span(self, operation_name):
        span_id = str(time.time())  # Simple span ID generation
        span = {"id": span_id, "operation_name": operation_name, "start_time": time.time()}
        self.spans.append(span)

    def end_span(self, span_id):
        for span in self.spans:
            if span["id"] == span_id:
                span["end_time"] = time.time() 
                break

    def add_tag(self, key, value):
        self.tags[key] = value

    def record_event(self, event_name, data={}):
        self.events.append({"name": event_name, "data": data})

    def transmit_trace(self): 
        # Implement logic to send trace data (spans, tags, events) to a centralized backend
        print("Sending trace:", self.spans, self.tags, self.events)

# Example usage
