    public async Task<XmlDocument> ProcessAsync(string filePath, string xPathExpression)
    {
        // ... (Logic to handle service discovery and authentication) ...
        var storageService = _storageServiceFactory.GetStorageService(filePath);
        if (_parsingTasks.TryGetValue(filePath, out var existingTask))
        {
            // Existing parsing task in progress - use result from previous task
            return await existingTask; 
        }

        var task = Task.Run(async () =>
        {
            try
            {
                var xmlData = await storageService.ReadDataAsync(filePath);
                var parsedDocument = _xmlParser.Parse(xmlData, xPathExpression);
                _cachingStrategy.Add(filePath, parsedDocument); // Add to cache
                return parsedDocument;
            }
            catch (Exception ex)
            {
                // ... (Error handling with logging and fallback strategy) ...
                throw; 
            }
        });

        _parsingTasks[filePath] = task;
        return await task;
    }

    // ... (Methods for cache management, error reporting, monitoring, etc.) ... 

}



```



