public class ResourceService {

    private final SdkMeterProvider meterProvider;
    private final Tracer tracer;

    public ResourceService() {
        // Initialize OpenTelemetry and Resilience4j components
        OpenTelemetry openTelemetry = OpenTelemetry.getGlobalInstance();
        this.meterProvider = openTelemetry.getMeterProvider();
        this.tracer = openTelemetry.getTracer("ResourceService");
    }

    @PUT("/resources/{id}")
    public ResponseEntity<Resource> updateResource(@PathVariable Long id, @RequestBody Resource resource) {
        // Validate request body using a custom schema validator
        if (!schemaValidator.validate(resource)) {
            return ResponseEntity.BAD_REQUEST.body(new ErrorResponse("Invalid resource data"));
        }

        Context context = tracer.buildSpan("updateResource").start();

        try {
            // Circuit breaker integration for external dependencies
            circuitBreaker.run(() -> {
                // Update the resource in the respective data store
                resourceStore.update(id, resource);
                return Resource.builder().id(id).data(resource.getData()).build();
            });

            // Calculate MD5 hash for updated resource
            String md5Hash = calculateMD5Hash(resource);
            return ResponseEntity.OK(Resource.builder().id(id).data(resource.getData()).md5Hash(md5Hash).build());
        } catch (Exception e) {
            // Handle exceptions and log details for debugging
            tracer.getCurrentSpan().setStatus(StatusCode.ERROR);
            logger.error("Error updating resource: ", e);
            return ResponseEntity.INTERNAL_SERVER_ERROR.body(new ErrorResponse("Resource update failed"));
        } finally {
            context.close();
        }
    }

    @DELETE("/resources/{id}")
    public ResponseEntity<Void> deleteResource(@PathVariable Long id) {
        // Circuit breaker integration for external dependencies
        circuitBreaker.run(() -> {
            // Delete the resource from the respective data store
            resourceStore.delete(id);
            return null;
        });

        return ResponseEntity.NO_CONTENT.build();
    }


}



