    private readonly ICache _cache;
    private readonly IDatabaseContext _database;
    private readonly ILogger<ContentUpdateService> _logger;
    private readonly RateLimiter _rateLimiter;

    public ContentUpdateService(ICache cache, IDatabaseContext database, ILogger<ContentUpdateService> logger)
    {
        _cache = cache;
        _database = database;
        _logger = logger;
        _rateLimiter = new RateLimiter(50, 60); // Max updates: 50 per IP in 60 seconds
    }

    [HttpPost("update-content/{id}")]
    public async Task<IActionResult> UpdateContentAsync([FromRoute] int id, [FromBody] ContentUpdateRequest request)
    {
        if (!_rateLimiter.Allow(HttpContext.Connection.RemoteIpAddress))
        {
            return StatusCode(429, "Rate limit exceeded."); 
        }

        var updatedContent = await _cache.GetAndLockAsync(id); // Cache first

        // Optimistic Locking
        if (updatedContent != null && updatedContent.Version == request.Version)
        {
            updatedContent.Content = request.NewContent;
            _cache.Update(id, updatedContent);
            return Ok(); 
        }
        else
        {
            // Cache miss or stale data, fall back to database with retry logic
            try
            {
                var dbContent = await _database.GetContentAsync(id);

                // Check for concurrency issues (optimistic locking)
                if (dbContent.Version == request.Version)
                {
                    dbContent.Content = request.NewContent;

                    await _database.SaveChangesAsync(); // Update database
                    _cache.Update(id, dbContent); 
                    return Ok();
                }
                else
                {
                    // Handle concurrency conflict (e.g., return conflict error)
                    return Conflict();
                }
            }
            catch (Exception ex)
            {
                // Retry logic with exponential backoff for transient failures
                _logger.LogError(ex, "Database update failed. Retrying...");

                // Implement retry logic here...
            }
        }

    }
}

