public class RandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly double _minValue;
    private readonly double _maxValue;

    public RandomValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomValue()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public double GenerateRandomValueExclusiveMax()
    {
        return _random.NextDouble() * (_maxValue - _minValue) ;
    }
}
