class TrafficProcessor(threading.Thread):
    def __init__(self, event_queue: queue.Queue, callback_registry: dict):
        super().__init__()
        self.event_queue = event_queue
        self.callback_registry = callback_registry

    def run(self):
        while True:
            event = self.event_queue.get()
            # Process event based on type using registered callbacks
            if event.event_type in self.callback_registry:
                self.callback_registry[event.event_type](event) 
            else:
                log_event(f"Unknown event type: {event.event_type}") 

            self.event_queue.task_done() 


class TrafficMonitoringSystem:
    def __init__(self):
        self.event_queue = queue.Queue()  
        self.callback_registry = {} 
        self.processors = [TrafficProcessor(self.event_queue, self.callback_registry) for _ in range(config["num_workers"])]

        for processor in self.processors:
            processor.start()  

    def register_callback(self, event_type: str, callback_function: Callable):
        self.callback_registry[event_type] = callback_function 

    def process_event(self, event: TrafficEvent):
        self.event_queue.put(event)  


# Example usage
