// runTests.js

const fs = require('fs');
const path = require('path');
const async = require('async');
const { retry, circuitBreaker, backpressure } = require('./utils'); // Import utilities

const frameworkConfig = JSON.parse(fs.readFileSync(path.join(__dirname, 'config.json'))); // Load configuration

class RunTests {
  constructor(testSuitePath) {
    this.testSuitePath = testSuitePath;
    this.tests = []; 
    this.concurrency = frameworkConfig.concurrency; // Set concurrency from config
    this.logger = new Logger(); // Initialize logger
  }

  loadTests() {
    // Dynamically load tests based on suite path
    const files = fs.readdirSync(this.testSuitePath);
    files.forEach((file) => {
      if (path.extname(file) === '.js') {
        const testModule = require(path.join(this.testSuitePath, file)); 
        this.tests.push(...testModule.default); // Assuming each module exports an array of tests
      }
    });
  }

  executeTests() {
    async.mapLimit(this.tests, this.concurrency, (test, callback) => {
      retry(circuitBreaker(backpressure(() => test())), 3, 1000, (error, result) => {
        if (error) {
          this.logger.error(`Test failed: ${test.name}`, error);
        } else {
          this.logger.info(`Test passed: ${test.name}`);
        }
        callback(null, result); 
      });
    }, (err, results) => {
      if (err) {
        console.error('Tests execution failed:', err);
      } else {
        // Generate and report test summary
      }
    });
  }

  start() {
    this.loadTests(); 
    this.executeTests();
  }
}

module.exports = RunTests;



