# dynamic_log_parser/log_parser.py

class DynamicLogParser:
    def __init__(self, config_service):
        self.config_service = config_service
        self.schema = self.config_service.get_schema()  
        self.factory_registry = {}

    def register_factory(self, id, factory_func):
        self.factory_registry[id] = factory_func

    def deserialize(self, json_data):
        try:
            data_obj = self.config_service.validate(json_data, self.schema)
            factory_id = data_obj.get('type') 
            factory_func = self.factory_registry.get(factory_id)
            if factory_func:
                return factory_func(data_obj)
            else:
                raise ValueError(f"Unsupported data type: {factory_id}")

        except ValidationError as e:
            raise DeserializationError(f"Invalid JSON data: {e.message}") from e

