#include <forward_list>
#include <iostream>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& search, const std::string& insert) {
  auto it = list.begin();
  while (it != list.end() && *it != search) {
    ++it;
  }
  if (it != list.end()) {
    list.insert_after(it, insert);
  } else {
    list.push_back(insert); 
  }
}

int main() {
  std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
  insertAfterFirstOccurrence(myList, "banana", "grape");
  for (const& str : myList) {
    std::cout << str << " ";
  }
  return 0;
}
