char* append_trailing_slash(const char* str, size_t str_len, size_t max_length) {
    if (str_len + 1 > max_length) {
        return NULL;
    }
    char* new_str = malloc(max_length);
    strncpy(new_str, str, str_len);
    new_str[str_len] = '/';
    new_str[max_length - 1] = '\0';
    return new_str;
}
