import hashlib
import os
import multiprocessing
from queue import Queue

def process_file(filepath, hash_queue):
    with open(filepath, 'rb') as f:
        chunk_size = 1024 * 1024  # Process in 1MB chunks
        data = f.read(chunk_size)
        while data:
            md5 = hashlib.md5()
            md5.update(data)
            hash_queue.put((filepath, md5.hexdigest()))
            data = f.read(chunk_size)

def compute_directory_hashes(directory, extensions_to_ignore=None):
    if not os.path.isdir(directory):
        raise ValueError("Invalid directory path")

    hash_queue = Queue()
    num_processes = multiprocessing.cpu_count()  # Utilize available CPU cores
    processes = [multiprocessing.Process(target=process_file, args=(filepath, hash_queue)) for filepath in get_files(directory, extensions_to_ignore)]

    for p in processes:
        p.start()

    for p in processes:
        p.join() 

    hashes = {filepath: hash for filepath, hash in hash_queue.get()}  # Collect results from queue
    return hashes

def get_files(directory, extensions_to_ignore=None):
    # Recursive function to list all files in a directory and subdirectories
    for root, dirs, files in os.walk(directory):
        for file in files:
            if not extensions_to_ignore or file.lower().endswith(tuple(extensions_to_ignore)):
                yield os.path.join(root, file)




```



