use std::process::{Command, Stdio};

fn main() {
    let output = Command::new("rustc")
        .args(["--crate-type", "lib"])
        .arg("src/main.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn_with(|| {
            let mut process = std::process::Command::new("rustc")
                .args(["--crate-type", "lib"])
                .arg("src/main.rs")
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn();

            // Capture compilation time and process memory usage
            let start_time = Instant::now();
            let start_rss = process.memory_info().rss;

            // Process output and errors
            let stdout = process.stdout.unwrap();
            let stderr = process.stderr.unwrap();

            process.wait().expect("Compilation failed");

            let end_time = Instant::now();
            let end_rss = process.memory_info().rss;

            // Calculate compilation time and memory usage change
            let duration = end_time - start_time;
            let rss_change = end_rss - start_rss;

            println!("Compilation Time: {:?}", duration);
            println!("Resident Set Size Change: {:?}", rss_change);

            Ok(())
        })
        .unwrap();

    // Process output and errors from the subprocess
    if let Err(e) = output.status().success() {
        eprintln!("Compilation failed with error: {}", e);
    } else {
        println!("Compilation successful!");
    }
}
