public class CreditCardProcessorService : ITransactionProcessor
{
    private readonly IPaymentGatewayFactory _gatewayFactory;
    private readonly IConfigurationService _configService; 

    public CreditCardProcessorService(IPaymentGatewayFactory gatewayFactory, IConfigurationService configService)
    {
        _gatewayFactory = gatewayFactory;
        _configService = configService;
    }

    public async Task<TransactionResult> ProcessTransactionAsync(TransactionRequest request)
    {
        var gatewayName = _configService.GetDefaultGatewayFor(request.CardBrand);
        var gateway = _gatewayFactory.CreateGateway(gatewayName); 

        try
        {
            return await gateway.ProcessTransactionAsync(request); 
        }
        catch (GatewayUnavailableException ex)
        {
            // Handle gateway outage, potentially retry with exponential backoff or failover
            return new TransactionResult { Status = "Error", Message = $"Gateway {gatewayName} unavailable: {ex.Message}" };
        }
    }
}

public interface IPaymentGateway
{
    Task<TransactionResult> ProcessTransactionAsync(TransactionRequest request);
}

public class StripeGateway : IPaymentGateway { ... } // Implementation for Stripe 

// Similar implementations for PayPal, Authorize.Net, FastPay


