// Import necessary libraries
const express = require('express');
const bodyParser = require('body-parser');
const redis = require('redis');
const kafka = require('kafka-node');

// Configure the Express app
const app = express();
app.use(bodyParser.json());

// Initialize Redis client for caching and session management
const redisClient = redis.createClient();

// Connect to Kafka topic for log ingestion
const producer = new kafka.KafkaJSProducer({ 
    id: 'log-processor',
    kafkaHost: 'localhost:9092'
});

// API endpoint for log ingestion
app.post('/logs', async (req, res) => {
  try {
    // Validate and sanitize incoming log data
    const logData = req.body;

    // Store log data in Redis cache for real-time analysis
    await redisClient.set(logData.id, JSON.stringify(logData));

    // Publish log data to Kafka topic for further processing
    producer.send([{topic: 'logs', messages: JSON.stringify(logData)}], (err, result) => {
      if (err) {
        console.error('Error publishing log data:', err);
      } else {
        console.log('Log data published successfully:', result);
      }
    });

    res.status(201).send('Log received');
  } catch (error) {
    console.error('Error processing log:', error);
    res.status(500).send('Internal server error');
  }
});


// Start the server
app.listen(3000, () => {
  console.log('Log microservice listening on port 3000');
});

```



