    // Wait for child process to finish or handle errors
    // Log command execution details and resource usage
  } else {
    perror("Fork failed");
  }
}

void *worker_thread(void *arg) {
  while (1) { 
    CommandConfig *config = get_next_command(); // Get a command from the queue
    if (config != NULL) {
      execute_command(config); 
      // Log successful execution
    }
  }
}

