```javascript
function copyBytes(dataChunks, byteCount) {
  const newBuffer = Buffer.allocUnsafe(byteCount);
  for (let i = 0; i < dataChunks.length && byteCount > 0; ++i) {
    const chunkLength = Math.min(byteCount, dataChunks[i].length);
    dataChunks[i].copy(newBuffer, byteCount - chunkLength, 0, chunkLength);
    byteCount -= chunkLength;
  }
  return newBuffer;
}
```




