namespace RandomValueGenerator
{
    public interface ILogWriter
    {
        void Write(string message);
    }

    public class FileLogWriter : ILogWriter
    {
        private readonly string _filePath;

        public FileLogWriter(string filePath)
        {
            _filePath = filePath;
        }

        public void Write(string message)
        {
            // Implement file writing logic here
        }
    }

    public class RandomValueGenerator
    {
        private readonly ILogWriter _logWriter;
        private readonly Random _random = new Random();

        public RandomValueGenerator(ILogWriter logWriter)
        {
            _logWriter = logWriter;
        }

        public int GenerateInt(int min, int max)
        {
            // Validate input range 
            if (min >= max)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            int randomValue = _random.Next(min, max + 1);

            _logWriter.Write($"Generated integer: {randomValue} at {DateTime.Now}");

            return randomValue;
        }

        public float GenerateFloat(float min, float max)
        {
            // Validate input range
            if (min >= max)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            float randomValue = (float)_random.NextDouble() * (max - min) + min;

            _logWriter.Write($"Generated float: {randomValue} at {DateTime.Now}");

            return randomValue;
        }

        public double GenerateDouble(double min, double max)
        {
            // Validate input range
            if (min >= max)
            {
                throw new ArgumentException("Minimum value must be less than maximum value.");
            }

            double randomValue = _random.NextDouble() * (max - min) + min;

            _logWriter.Write($"Generated double: {randomValue} at {DateTime.Now}");

            return randomValue;
        }
    }
} 

```


