use rand::Rng;

pub fn generate_random_string(length: usize, charset: &str) -> String {
    let mut rng = rand::thread_rng();
    charset.chars()
        .map(|c| c as u32)
        .collect::<Vec<_>>()
        .into_iter()
        .take(length)
        .map(|_| rng.gen_range(0..charset.len()))
        .map(|i| charset.chars().nth(i).unwrap())
        .collect()
}

pub fn hash_password(password: &str) -> String {
    use sha2::Sha256;
    let mut hasher = Sha256::new();
    hasher.update(password.as_bytes());
    hasher.finalize().to_hex()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_random_string() {
        let random_string = generate_random_string(10, "abcdefghijklmnopqrstuvwxyz");
        assert!(random_string.len() == 10);
        for char in random_string.chars() {
            assert!(char.is_lowercase());
        }
    }

    #[test]
    fn test_hash_password() {
        let hashed_password = hash_password("testpassword");
        assert!(hashed_password.len() > 0);
    }
}


