struct RecordFactory {
    record_types: Arc<Mutex<Vec<Box<dyn RecordType>>>>,
}

impl RecordFactory {
    fn new() -> Self {
        RecordFactory {
            record_types: Arc::new(Mutex::new(vec![])),
