func loadStateFromFile(filename string) State {
	data, err := ioutil.ReadFile(filename)
	if err != nil {
		log.Fatal("Error reading state file:", err)
	}

	var state State
	err = json.Unmarshal(data, &state)
	if err != nil {
		log.Fatal("Error unmarshaling state file:", err)
	}

