use tokio::sync::{mpsc, oneshot};
use tokio::task;

async fn process_data(data: String) {
    // Perform data processing here
    println!("Processed data: {}", data);
}

#[tokio::main]
async fn main() {
    let (tx, rx) = mpsc::channel(1024);

    // Spawn worker tasks to process incoming data
    for _ in 0..8 { // Adjust number of workers based on load
        task::spawn(async move {
            while let Some(data) = rx.recv().await {
                process_data(data).await;
            }
        });
    }

    // Simulate receiving data from multiple sources
    for i in 0..100 {
        let data = format!("Data {}", i);
        tx.send(data).await.unwrap();
    }

    // Keep the main thread alive to prevent premature termination
    tokio::runtime::Runtime::new().unwrap().block_on(async {})
}


