async function fetchAndProcessElements(rootElement, cssSelector, customFilter) {
  const results = [];

  const traverse = async (node) => {
    if (node.nodeType === Node.ELEMENT_NODE && node.matches(cssSelector)) {
      if (customFilter && !customFilter(node)) return; 
      results.push(node);
    }

    for (let i = 0; i < node.childNodes.length; i++) {
      await traverse(node.childNodes[i]);
    }
  };

  await traverse(rootElement);
  return Promise.resolve(results);
} 
