#include <boost/asio.hpp>
#include <boost/bind/bind.hpp>
#include <boost/shared_ptr.hpp>

using boost::asio::ip::tcp;

class SandeshClient {
public:
    SandeshClient(const std::string& serverAddress) 
        : io_service_(), socket_(io_service_), serverAddress_(serverAddress) {}

    void SendGetRequest(const std::string& path, const std::function<void(const std::string&)>& callback) {
        boost::shared_ptr<SandeshRequest> request(new SandeshRequest(path));
        requests_.push_back(request);
        socket_.async_connect(tcp::endpoint(tcp::v4(), 50051), 
                             boost::bind(&SandeshClient::HandleConnect, this, std::placeholders::_1, request, callback));
    }

private:
    void HandleConnect(const boost::system::error_code& error, boost::shared_ptr<SandeshRequest> request, const std::function<void(const std::string&)>& callback) {
        if (!error) {
            std::stringstream ss;
            ss << "GET " << request->path << " HTTP/1.1\r\nHost: localhost\r\n\r\n";
            socket_.async_write_some(boost::asio::buffer(ss.str()), 
                                     boost::bind(&SandeshClient::HandleWrite, this, std::placeholders::_1, request, callback));
        } else {
            callback("Connection failed: " + error.message());
        }
    }

    void HandleWrite(const boost::system::error_code& error, std::size_t bytes_transferred, boost::shared_ptr<SandeshRequest> request, const std::function<void(const std::string&)>& callback) {
        if (!error) {
            std::array<char, 1024> buffer;
            socket_.async_read_some(boost::asio::buffer(buffer), 
                                     boost::bind(&SandeshClient::HandleRead, this, std::placeholders::_1, std::placeholders::_2, request, callback));
        } else {
            callback("Write failed: " + error.message());
        }
    }

    void HandleRead(const boost::system::error_code& error, std::size_t bytes_transferred, boost::shared_ptr<SandeshRequest> request, const std::function<void(const std::string&)>& callback) {
        if (!error) {
            std::string response = std::string(buffer_.data(), bytes_transferred);
            callback(response);
        } else {
            callback("Read failed: " + error.message());
        }
    }

    boost::asio::io_service io_service_;
    tcp::socket socket_;
    std::string serverAddress_;
    std::vector<boost::shared_ptr<SandeshRequest>> requests_;
};



```




