void execute_commands(CommandInfo **commands, int num_commands) {
    for (int i = 0; i < num_commands; ++i) {
        pid_t pid = fork();
        if (pid == 0) { // Child process
            // Execute command in child process
            log_command(commands[i]->command);
            execlp("/bin/sh", "sh", "-c", commands[i]->command, NULL);
            perror("Command execution failed");
            exit(1);
        } else if (pid > 0) { // Parent process
            commands[i]->pid = pid;
            log_command("Command started: ");
            // Add command information to a data structure for tracking
        } else {
            perror("Fork failed");
            exit(1);
        }
    }

    // Monitor and handle subprocesses here
}

void cleanup_commands(CommandInfo **commands, int num_commands) {
    for (int i = 0; i < num_commands; ++i) {
        waitpid(commands[i]->pid, NULL, WNOHANG);
        // Log final status for each command
    }
}

int main() {
    // Example usage:
    CommandInfo *commands[] = {
        { "ls -l", 0 },
        { "date", 0 }
    };
    execute_commands(commands, sizeof(commands) / sizeof(CommandInfo *));
    cleanup_commands(commands, sizeof(commands) / sizeof(CommandInfo *));

    return 0;
}
