[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly IResourceRepository _repository;

    public ResourceController(IResourceRepository repository)
    {
        _repository = repository;
    }

    [HttpPut("{id}")]
    public IActionResult UpdateResource(int id, [FromBody] Resource resource)
    {
        if (!_repository.Exists(id))
        {
            return NotFound();
        }

        _repository.Update(id, resource);
        return Ok(_repository.GetById(id));
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteResource(int id)
    {
        if (!_repository.Exists(id))
        {
            return NotFound();
        }

        _repository.Delete(id);
        return Ok(new Resource()); // Return a new resource with default values
    }
}

