using System;
using System.Xml;
using System.XPath;

public class XmlParser
{
    public static string GetFirstElementText(string xmlPath, string elementName)
    {
        try
        {
            var doc = new XmlDocument();
            doc.Load(xmlPath);
            var xpathNavigator = doc.CreateNavigator();
            var result = xpathNavigator.SelectSingleNode($"//" + elementName);

            if (result == null)
            {
                throw new Exception($"No element found with name '{elementName}' in XML document.");
            }
            return result.InnerXml; 
        }
        catch (Exception ex)
        {
            throw new Exception($"Error parsing XML: {ex.Message}"); 
        }
    }
}



