typedef struct {
    node_t* head;
    pthread_mutex_t mutex;
} crc_list_t;

crc_list_t* crc_list_create() {
    crc_list_t* list = (crc_list_t*)malloc(sizeof(crc_list_t));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void crc_list_destroy(crc_list_t* list) {
    node_t* current = list->head;
    while (current != NULL) {
        // ... (Handle memory deallocation for each node)
        current = current->next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void crc_list_insert(crc_list_t* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);
    // ... (Insert new node into the linked list)
    pthread_mutex_unlock(&list->mutex);
}

void crc_list_delete(crc_list_t* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);
