using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private readonly ConcurrentRandom _random = new ConcurrentRandom(); 
    private readonly SemaphoreManager _semaphoreManager = new SemaphoreManager(1); // Adjust semaphore count as needed

    public int GenerateRandom(int min, int max)
    {
        _semaphoreManager.Acquire(); // Acquire semaphore before generating random value
        try
        {
            if (min > max)
            {
                Console.WriteLine("Invalid range: Minimum must be less than or equal to maximum.");
                return -1; // Or handle invalid input differently
            }

            int randomValue = _random.Next(min, max + 1); 
            return randomValue;
        }
        finally
        {
            _semaphoreManager.Release(); // Release semaphore after generating random value
        }
    }

    // ... (Add other methods as needed)
}


public class SemaphoreManager : IDisposable
{
    private readonly SemaphoreSlim _semaphore;

    public SemaphoreManager(int initialCount)
    {
        _semaphore = new SemaphoreSlim(initialCount); 
    }

    public void Acquire() => _semaphore.Wait();
    public void Release() => _semaphore.Release();

    public void Dispose()
    {
        _semaphore?.Dispose(); // Ensure proper disposal of semaphore
    }
}
```



**Note:** This code provides a basic structure and should be further developed according to your specific requirements and use cases. Remember to handle potential exceptions, implement logging for error tracking, and add comprehensive unit tests to ensure the reliability and robustness of your `RandomValueGenerator` class.']

