        Thread(target=self._replicate_data, args=(source_database, target_database)).start()

    def _replicate_data(self, source_database, target_database):
        while True:
            # Retrieve changes from the source database
            changes = self.database_connectors[source_database].get_changes()  

            # Apply changes to the target database 
            for change in changes:
                try:
