public class ApiGateway {

    private final ServiceRegistry serviceRegistry;
    private final AuthenticationHandler authenticationHandler;
    private final RateLimiter rateLimiter;
    private final LoadBalancer loadBalancer;
    private final ErrorHandler errorHandler;

    // Constructor with dependencies injected
    public ApiGateway(ServiceRegistry serviceRegistry, 
                     AuthenticationHandler authenticationHandler,
                     RateLimiter rateLimiter,
                     LoadBalancer loadBalancer, 
                     ErrorHandler errorHandler) {
        this.serviceRegistry = serviceRegistry;
        this.authenticationHandler = authenticationHandler;
        this.rateLimiter = rateLimiter;
        this.loadBalancer = loadBalancer;
        this.errorHandler = errorHandler;
    }

    public Response handleRequest(HttpRequest request) {
        // 1. Authentication and Authorization
        if (!authenticationHandler.authenticate(request)) {
            return errorHandler.handleUnauthorized();
        }

        // 2. Rate Limiting
        if (rateLimiter.isLimited(request)) {
            return errorHandler.handleRateLimitExceeded();
        }

        // 3. Service Routing
        ServiceInstance instance = loadBalancer.selectInstance(request);

        // 4. Request Forwarding and Response Handling
        Response response = client.sendRequest(instance, request);

        // 5. Error Handling (if needed)
        return errorHandler.handle(response);
    }


}
