#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
} Item;

int loadResourceBundle(const char* path, Item** bundle, size_t* count) {
  FILE* file = fopen(path, "r");
  if (file == NULL) {
    perror("Error opening file");
    return 1;
  }

  // Read number of items from file
  size_t numItems;
  fscanf(file, "%zu", &numItems);

  *bundle = malloc(numItems * sizeof(Item));
  if (*bundle == NULL) {
    perror("Memory allocation failed");
    fclose(file);
    return 1;
  }

  // Read item data from file and store in bundle
  for (size_t i = 0; i < numItems; ++i) {
    (*bundle)[i].name = malloc(sizeof(char) * 100); // Allocate memory for name, adjust size if needed
    if ((*bundle)[i].name == NULL) {
      perror("Memory allocation failed");
      free(*bundle);
      fclose(file);
      return 1;
    }
    fscanf(file, "%s", (*bundle)[i].name);
  }

  fclose(file);
  *count = numItems;
  return 0;
}



