import java.util.*;

public class DisjointPairCounter {

    private int[] parent;
    private int[] rank;

    public DisjointPairCounter(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int countDisjointPairs(int[] arr) {
        int count = 0;
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (find(arr[i]) != find(arr[j])) {
                    union(arr[i], arr[j]);
                    count++;
                }
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
        return count;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7, 8};
        DisjointPairCounter counter = new DisjointPairCounter(9); // Assuming array indices from 0 to 8
        int result = counter.countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + result);
    }
}
