using System.Threading.Tasks;

namespace CommandOrchestrator
{
    public class CommandOrchestrator
    {
        private readonly int _maxConcurrentTasks;
        private readonly SemaphoreSlim _semaphore;
        private readonly ILoggingService _loggingService;
        private readonly IDatabaseManager _databaseManager;

        public CommandOrchestrator(int maxConcurrentTasks, ILoggingService loggingService, IDatabaseManager databaseManager)
        {
            _maxConcurrentTasks = maxConcurrentTasks;
            _semaphore = new SemaphoreSlim(_maxConcurrentTasks);
            _loggingService = loggingService;
            _databaseManager = databaseManager;
        }

        public async Task<Guid> SubmitCommandAsync(string commandData)
        {
            var guid = Guid.NewGuid();
            await _databaseManager.InsertTaskAsync(guid, commandData);
            _loggingService.LogInformation($"Command {guid} submitted.");
            return guid;
        }

        public async Task ProcessCommandsAsync()
        {
            while (true)
            {
                var task = await _databaseManager.GetPendingTaskAsync();
                if (task != null)
                {
                    await _semaphore.WaitAsync();
                    try
                    {
                        _loggingService.LogInformation($"Processing command {task.Id}.");
                        // Execute the command logic here
                    }
                    finally
                    {
                        _semaphore.Release();
                        _databaseManager.UpdateTaskStatus(task.Id, TaskStatus.Completed);
                    }
                }
            }
        }
    }
}
```



**Explanation:**

This code provides a basic structure for the `CommandOrchestrator` module. It includes:

- **Constructor:** Initializes variables like maximum concurrent tasks, semaphore, logging service, and database manager.
- **SubmitCommandAsync:** Handles command submission, stores metadata in the database, and logs information. 
- **ProcessCommandsAsync:** Continuously fetches pending tasks from the database, processes them concurrently using the semaphore, updates task status, and logs relevant information.

**Remember:** This is a simplified example. To implement the full functionality outlined in the requirements, you'll need to:


* Integrate with REST APIs, databases, and a logging service.
