    public IDataReader ProcessBatch(List<DataItem> items) throws Exception {
        List<String> sqlCommands = new ArrayList<>();
        List<Object[]> parameters = new ArrayList<>();

        for (DataItem item : items) {
            // Generate SQL command and parameters based on item data
            sqlCommands.add(generateSqlCommand(item));
            parameters.add(prepareParameters(item));
        }

        Connection connection = databaseConnector.getConnection();
        try (PreparedStatement ps = connection.prepareStatement(String.join(";", sqlCommands))) {
            for (int i = 0; i < parameters.size(); i++) {
                ps.clearParameters();
                Object[] params = parameters.get(i);
                for (int j = 0; j < params.length; j++) {
                    ps.setObject(j + 1, params[j]);
                }
                ps.addBatch();
            }
            return ps.executeQuery();
        } catch (Exception e) {
            // Handle errors gracefully, log and potentially retry
            throw new RuntimeException("Error processing batch", e);
        }
    }

