import re, json

def process_clinic_config(filename):
    with open(filename, "r") as f:
        lines = f.readlines()

    clinics = []
    for line in sorted(lines):
        match = re.search(r'name="([^"]+)"', line)
        if match:
            clinic_name = match.group(1)
            sequence = re.search(r'sequence=(\d+)', line)
            if sequence:
                clinics.append({"name": clinic_name, "sequence": int(sequence.group(1))})

    return clinics


if __name__ == "__main__":
    try:
        config_data = process_clinic_config("clinic_config.json")
        print(json.dumps(config_data, indent=4)) 
    except FileNotFoundError:
        print("Error: clinic_config.json not found.")
    except Exception as e:
        print(f"An error occurred: {e}")
