#include <random>
#include <mutex>

class RandomNumberGenerator {
 private:
  static RandomNumberGenerator* instance;
  std::mt19937 generator;
  std::uniform_real_distribution<> uniformDist;
  std::normal_distribution<> normalDist;
  int seedValue;
  DistributionType distributionType;
  double minRange, maxRange;

 public:
  static RandomNumberGenerator& getInstance() {
    if (instance == nullptr) {
      instance = new RandomNumberGenerator();
    }
    return *instance;
  }

  void initialize(int seedValue, DistributionType distributionType, double minRange, double maxRange) {
    this->seedValue = seedValue;
    this->distributionType = distributionType;
    this->minRange = minRange;
    this->maxRange = maxRange;
    generator.seed(seedValue);
    if (distributionType == DistributionType::UNIFORM) {
      uniformDist = std::uniform_real_distribution<>(minRange, maxRange);
    } else if (distributionType == DistributionType::NORMAL) {
      normalDist = std::normal_distribution<>(0.0, 1.0);
    }
  }

  double generateRandom() {
    if (distributionType == DistributionType::UNIFORM) {
      return uniformDist(generator);
    } else if (distributionType == DistributionType::NORMAL) {
      return normalDist(generator);
    }
    return 0.0;
  }

 private:
  enum DistributionType { UNIFORM, NORMAL };
};

// ... [Singleton Instance Initialization]



