import os
import hashlib
from concurrent.futures import ThreadPoolExecutor

def calculate_md5(file_path):
    with open(file_path, 'rb') as f:
        chunk_size = 1024 * 1024  # 1 MB chunk size
        md5_hash = hashlib.md5()
        for chunk in iter(lambda: f.read(chunk_size), b''):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def process_directory(dir_path, excluded_extensions=None):
    ignore_extensions = set(excluded_extensions) if excluded_extensions else set()
    with ThreadPoolExecutor(max_workers=10) as executor:  # Adjust worker count based on system resources
        futures = [executor.submit(calculate_md5, file_path) for file_path in os.listdir(dir_path) 
                   if os.path.isfile(os.path.join(dir_path, file_path)) and not (file_path.endswith(tuple(ignore_extensions)))]
        for future in futures:
            try:
                md5_hash = future.result()  # Handle potential exceptions
                print(f"MD5 hash for {file_path}: {md5_hash}")
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

if __name__ == "__main__":
    dir_path = "/path/to/directory"  # Replace with your directory path
    excluded_extensions = [".log", ".tmp"] # Add extensions to ignore, if any
    process_directory(dir_path, excluded_extensions)
``` 



