use std::env;
use std::io::{CreateExt, Write};
use std::path::PathBuf;

fn create_directory_and_set_env(
    directory_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let path = PathBuf::from(directory_name);

    // Check if the directory already exists.
    if path.exists() {
        println!("Directory {} already exists.", directory_name);
        return Ok(()); 
    }

    // Create the directory.
    std::fs::create_dir(&path)?;

    // Set the environment variable.
    let env_var = format!("{}_PATH", directory_name.to_uppercase());
    env::set_var(&env_var, path.to_str().unwrap());

    println!("Created directory: {} and set environment variable: {}", directory_name, env_var);

    Ok(())
}

fn main() {
    let directory_name = "my_traffic_data"; 
    create_directory_and_set_env(directory_name).unwrap(); 
}
```



