// Example Async Reduce Function using callbacks

async function asyncReduce(numbers, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    let index = 0;
    const processNumber = () => {
      if (index < numbers.length) {
        callback(accumulator, numbers[index], (err, result) => {
          if (err) {
            reject(err);
            return;
          }
          accumulator = result;
          index++;
          processNumber(); // Continue processing
        });
      } else {
        resolve(accumulator); 
      }
    };
    processNumber();
  });
}

// Example Usage:
asyncReduce([1, 2, 3], 0, (acc, num) => acc + num)
  .then(result => console.log('Result:', result)) // Output: Result: 6
  .catch(err => console.error('Error:', err));

```



