typedef struct {
    int N; 
    NFAPI_CRC_INDICATION_PDU_T **array;
} CRC_MemoryManager;

// ... Implement logging system calls 

void *allocate_crc_indications(int N, CRC_MemoryManager *manager) {
  if (N <= 0) {
    log_warning("Invalid N value: %d", N);
    return NULL;
  }

  pthread_mutex_lock(&manager->lock); // Assume a lock for thread safety

  if (manager->array != NULL && manager->N >= N) {
    // Reuse existing memory if sufficient
    manager->N = N; 
    pthread_mutex_unlock(&manager->lock);
    return manager->array; 
  }

  manager->array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
  if (manager->array == NULL) {
    log_error("Memory allocation failed");
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Handle memory allocation failure
  }

  for (int i = 0; i < N; ++i) {
      manager->array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
      if (manager->array[i] == NULL) {
        // Handle allocation failure for individual PDUs
        log_error("Memory allocation failed for PDU %d", i);
        // Attempt to free previously allocated memory 
        for (int j = 0; j < i; ++j) {
          free(manager->array[j]);
        }
        free(manager->array);
        pthread_mutex_unlock(&manager->lock);
        return NULL; 
      }
  }

  manager->N = N;
  pthread_mutex_unlock(&manager->lock);
  return manager->array;
}


void release_crc_indications(CRC_MemoryManager *manager) {
  // ... Implementation to free allocated memory and resources
}



