        // Constructor with parameter injection for dependencies
        public SecureDataProcessor(string connectionString, 
                                 IRandomStringGenerator randomStringGenerator,
                                 IPasswordHasher passwordHasher,
                                 IEncryptionService encryptionService)
        {
            _connectionString = connectionString;
            _randomStringGenerator = randomStringGenerator;
            _passwordHasher = passwordHasher;
            _encryptionService = encryptionService;
        }

        // Methods for secure data operations 
        public async Task<string> GenerateSecureRandomStringAsync(int length, string characterSet)
        {
            // Call the injected random string generator
            return await _randomStringGenerator.GenerateStringAsync(length, characterSet);
        }

        public async Task<string> HashPasswordAsync(string password)
        {
            // Use the injected password hasher 
            return await _passwordHasher.HashAsync(password);
        }

        public async Task<string> EncryptDataAsync(string data, string key)
        {
            // Utilize the injected encryption service
            return await _encryptionService.EncryptAsync(data, key);
        }

        // Example SQL interaction method (demonstration only)
        public async Task<int> ExecuteQueryAsync(string query, params object[] parameters)
        {
