    public TransactionHasher(IAlgorithmFactory algorithmFactory, ILogger logger, IKmsClient kmsClient, ICache<string, HashingAlgorithm> algorithmCache)
    {
        _algorithmFactory = algorithmFactory;
        _logger = logger;
        _kmsClient = kmsClient;
        _algorithmCache = algorithmCache;
    }

    public byte[] CalculateHash(string data, string algorithmName)
    {
        // Cache hit check 
        if (_algorithmCache.TryGetValue(algorithmName, out var hashingAlgorithm))
        {
            // Use cached algorithm
            return hashingAlgorithm.CalculateHash(data);
        }

        // Retrieve key from KMS
        var key = _kmsClient.GetKey(algorithmName); 

        // Create and cache the algorithm instance
        hashingAlgorithm = _algorithmFactory.CreateAlgorithm(algorithmName, key);
        _algorithmCache.AddOrUpdate(algorithmName, hashingAlgorithm);

        return hashingAlgorithm.CalculateHash(data);
    }

    // Other methods for validation, rate limiting, backoff, etc.

}



