    def __init__(self, api_url="https://pokeapi.co/api/v2"):
        self.api_url = api_url
        self.pokemon_registry = {} 

    def register_pokemon_factory(self, pokemon_type, factory_func):
        self.pokemon_registry[pokemon_type] = factory_func

    def fetch_pokemon_data(self, pokemon_name):
        url = f"{self.api_url}/pokemon/{pokemon_name}"
        try:
            response = requests.get(url)
            response.raise_for_status()  
            return response.json()
        except requests.exceptions.RequestException as e:
            raise PokemonAPIError(f"Error fetching data for {pokemon_name}: {e}")

    def create_pokemon(self, data):
        pokemon_type = data['types'][0]['type']['name'] 
        factory_func = self.pokemon_registry.get(pokemon_type)
        if factory_func:
            return factory_func(data)
        else:
            raise ValueError(f"Unknown pokemon type: {pokemon_type}")

    # ... (Additional methods for parsing data, caching, etc.)

class BasePokemon(ABC):
    @abstractmethod
    def __init__(self, data):
        pass

    def get_name(self):
        return self.name

    def get_types(self):
        return self.types

    # ... (Other methods for accessing Pokémon attributes)


class FirePokemon(BasePokemon): 
    def __init__(self, data):
        super().__init__(data) 
        self.name = data['name']
        self.types = [t['type']['name'] for t in data['types']]

    # ... (Fire-specific attributes and methods)


class WaterPokemon(BasePokemon):
