        super().__init__(data) 
        self.name = data['name']
        self.types = [t['type']['name'] for t in data['types']]

    # ... (Water-specific attributes and methods)



pokemon_parser = PokemonParser() 
pokemon_parser.register_pokemon_factory('fire', FirePokemon)  
pokemon_parser.register_pokemon_factory('water', WaterPokemon)


