// ... (Extensive C++ code for framework implementation omitted due to complexity) ...

/**
 * Java function to count disjoint pairs in an integer array using Union-Find.
 */
public class DisjointPairs {

    static int[] parent; // Array to store parent nodes of the Union-Find data structure
    static int[] rank;  // Array to store the rank (height) of each tree in the Union-Find data structure

    public static int countDisjointPairs(int[] arr) {
        int n = arr.length;
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; ++i) {
            parent[i] = i; // Initially, each element is its own parent
            rank[i] = 0;    // Initial rank of each tree is 0
        }

        long startTime = System.currentTimeMillis();

        int count = 0;
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (find(arr[i]) != find(arr[j])) { // Check if elements belong to different sets
                    unionSets(arr[i], arr[j]); // Union the sets containing the elements
                    count++;
                    System.out.println("Pair: (" + arr[i] + ", " + arr[j] + "), Time taken (ms): " + (System.currentTimeMillis() - startTime));
                }
            }
        }

        return count;
    }

    private static int find(int u) {
        if (parent[u] == u) { // Base case: if u is the parent of itself, it's the root
            return u;
        }
        return find(parent[u]); // Recursively find the root of the set containing u
    }

    private static void unionSets(int u, int v) {
        int rootU = find(u); 
        int rootV = find(v);
        if (rank[rootU] < rank[rootV]) { // Attach smaller tree to larger one
            parent[rootU] = rootV;
        } else if (rank[rootU] > rank[rootV]) {
            parent[rootV] = rootU;
        } else { 
            parent[rootV] = rootU; 
            rank[rootU]++; // Increase rank of the merged tree
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5};
        int count = countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + count);
    }

}
