struct record {
  int value;
};

int main() {
  const int num_records = 100;
  long* offsets = new long[num_records];
  int* keys = new int[num_records];
  record* records = new record[num_records];

  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> distrib(0, 100);

  for (int i = 0; i < num_records; ++i) {
    offsets[i] = distrib(gen);
    keys[i] = distrib(gen);
    records[i].value = distrib(gen);
  }

  // ... further processing of records, offsets, and keys ...

  delete[] offsets;
  delete[] keys;
  delete[] records;
  return 0;
}


