import hashlib

def calculate_md5_hash(file_path):
  with open(file_path, 'rb') as f:
    hash_object = hashlib.md5()
    while True:
      chunk = f.read(4096)
      if not chunk:
        break
      hash_object.update(chunk)
  return hash_object.hexdigest() 
