public class DynamicJsonMicroservice : IHostedService
{
    private readonly ILogger<DynamicJsonMicroservice> _logger;
    private readonly IDataRepository _dataRepository;
    private readonly IJsonFactory _jsonFactory;
    private readonly IDistributedCache _distributedCache;

    // ... (Constructor, Dependency Injection) ...

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        // ... Initialize CDN clients and listeners for cache invalidation ... 

        _logger.LogInformation("Dynamic JSON microservice started.");
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        // ... Graceful shutdown logic ... 
        _logger.LogInformation("Dynamic JSON microservice stopped.");
    }

    [HttpPost("update/{id}")]
    public async Task<IActionResult> UpdateData([FromBody] dynamic data, string id, CancellationToken cancellationToken)
    {
        // ... Validate input data ... 

        using var semaphore = new SemaphoreSlim(100); // Limit concurrent updates to 100

        await semaphore.WaitAsync(cancellationToken);

        try
        {
            var jsonData = _jsonFactory.CreateInstance(id).Deserialize(data); // Deserialize JSON using factory

            await _dataRepository.UpdateDataAsync(jsonData, id, cancellationToken); 

            _distributedCache.Remove($"json/{id}"); // Invalidate cache

            return Ok("Update successful.");
        }
        catch (Exception ex)
        {
            // ... Log error and implement retry logic with exponential backoff ... 
            return StatusCode(500, "Failed to update data.");
        }
        finally
        {
            semaphore.Release(); // Release semaphore for the next update
        }
    }
}



```


