EVP_CIPHER_CTX* init_aes_cipher(const char* password) {
  unsigned char key[32]; // Fixed key length 256 bits
  unsigned char iv[16];  // Fixed IV length 128 bits

  // Derive encryption key using SHA-256 (replace with your preferred algorithm)
  EVP_MD_CTX* md_ctx = EVP_MD_CTX_new();
  EVP_DigestInit(md_ctx, EVP_sha256());
  EVP_DigestUpdate(md_ctx, password, strlen(password));
  EVP_DigestFinal(md_ctx, key, NULL);
  EVP_MD_CTX_free(md_ctx);

  // Initialize AES-256-CBC cipher context
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
